import datetime
from typing import List

from ...base.client import BaseClient


class MiscMethods(BaseClient):
    """
    Методы группы 'Разное' из https://im-docs.corp.mail.ru/
    """

    async def rapi_misc_support(
        self,
        message: str,
        platform: str,
        appVersion: str,
        osVersion: str,
        device: str,
        attachmentFileId: str,
        screenshotFileIdList: List[str],
    ):
        """
        Отправка пользовательского отзыва
        :param message:
        :param platform:
        :param appVersion:
        :param osVersion:
        :param device:
        :param attachmentFileId:
        :param screenshotFileIdList:
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/misc/support",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "sn": self.uin,
                    "message": message,
                    "platform": platform,
                    "appVersion": appVersion,
                    "osVersion": osVersion,
                    "device": device,
                    "attachmentFileId": attachmentFileId,
                    "screenshotFileIdList": screenshotFileIdList,
                },
            },
        )

    async def misc_preview_getPreview(self, url: str, domain: str = "1", v: str = "1"):
        return await self.request(
            method="GET",
            url="/".join([self.base_url, "misc/preview/getPreview"]),
            params={
                "a": self.token,
                "domain": domain,
                "k": self.devId,
                "ts": int(datetime.datetime.now().timestamp()),
                "url": url,
                "v": v,
                "debug": "1",
            },
            ignore_check=True,
        )

    async def misc_preview_getUrlContent(self, url: str):
        return await self.request(
            method="GET",
            url=f"{self.binary_api_url}/misc/preview/getURLContent",
            params={"aimsid": self.aimsid, "url": url},
        )
